using System.Collections.Generic;public class Solution{public bool IsValid(string s){var st=new Stack<char>();foreach(char c in s){if(c=='('||c=='['||c=='{')st.Push(c);else{if(st.Count==0)return false;char o=st.Pop();if(c==')'&&o!='('||c==']'&&o!='['||c=='}'&&o!='{')return false;}}return st.Count==0;}}
